const log = find_block({ names: ["oak_log", "spruce_log", "birch_log", "cherry_log", "dark_oak_log", "pale_oak_log", "mangrove_log", "acacia_log", "jungle_log"], max_distance: 96 });
if (!log) {
  const here = position();
  await move_to(here.x + 24, here.y, here.z + 24);
  return { done: false, detail: 'no tree within 96; walking on' };
}
const chopped = await dig(log.x, log.y, log.z);
if (!chopped.ok) {
  return { done: false, detail: chopped.detail };
}
await leave_at_depot();
return { done: true, detail: 'mined a log and left the bag at the depot' };
